<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
const $q=useQuasar(), distributions=reactive({desktop:null,cloud:null}),busy=ref(false),progress=ref(0),packageType=ref('desktop')
const defaults=type=>({version:'',notes:'',url:'',filename:`AitoNotify-${type==='cloud'?'Cloud':'Desktop'}.zip`,source:'file',file:null})
const forms=reactive({desktop:defaults('desktop'),cloud:defaults('cloud')})
const form=computed(()=>forms[packageType.value]), current=computed(()=>distributions[packageType.value]),kindLabel=computed(()=>packageType.value==='cloud'?'Cloud / Render':'Desktop')
const headers=()=>({Authorization:`Bearer ${localStorage.getItem('aito_admin_token')||''}`})
const size=bytes=>`${(Number(bytes||0)/1024/1024).toFixed(1)} MB`
const failure=error=>$q.notify({type:'negative',message:error.response?.data?.message||'Não foi possível concluir a operação do pacote.'})
async function load(){try{const data=(await api.get('/admin/products/aitonotify/packages',{headers:headers()})).data.data;distributions.desktop=data.slots?.desktop||data.current||null;distributions.cloud=data.slots?.cloud||data.cloud||null}catch(error){failure(error)}}
async function submitPublish(){
 const type=packageType.value,input=forms[type]
 busy.value=true;progress.value=0
 try{
  if(input.source==='file'){const query=new URLSearchParams({version:input.version.trim(),notes:input.notes,filename:input.file.name,packageType:type});await api.post('/admin/products/aitonotify/packages/upload?'+query,input.file,{headers:{...headers(),'Content-Type':'application/octet-stream'},timeout:15*60000,onUploadProgress:event=>{progress.value=event.total?event.loaded/event.total:0}})}
  else await api.post('/admin/products/aitonotify/packages/import',{version:input.version.trim(),notes:input.notes,url:input.url,filename:input.filename,packageType:type},{headers:headers(),timeout:15*60000})
  input.file=null;progress.value=1;await load();$q.notify({type:'positive',message:`Pacote ${kindLabel.value} publicado. O botão do cliente usa o arquivo atual.`})
 }catch(error){failure(error)}finally{busy.value=false}
}
function publish(){
 if(busy.value)return
 if(!/^[a-zA-Z0-9][a-zA-Z0-9._-]{0,39}$/.test(form.value.version.trim())||(form.value.source==='file'&&!form.value.file))return $q.notify({type:'warning',message:'Informe uma versão válida e escolha um arquivo ZIP/RAR.'})
 if(form.value.source==='drive'&&(!form.value.url.trim()||! /\.(zip|rar)$/i.test(form.value.filename)))return $q.notify({type:'warning',message:'Informe o link do Drive e um nome de arquivo ZIP/RAR.'})
 if(current.value)$q.dialog({title:`Substituir o pacote ${kindLabel.value}?`,message:`A versão ${current.value.version} será substituída pela ${form.value.version}. O arquivo anterior é removido do servidor; mantenha seu histórico no Drive.`,cancel:true,persistent:true}).onOk(submitPublish)
 else submitPublish()
}
async function testDownload(){try{const data=(await api.post(`/admin/products/aitonotify/packages/${current.value.id}/ticket`,{packageType:packageType.value},{headers:headers()})).data.data;window.location.assign(data.url)}catch(error){failure(error)}}
onMounted(load)
</script>
<template><section class="package-manager">
 <header><q-icon name="mdi-package-variant-closed-check" size="30px"/><div><h3>Distribuições do produto</h3><p>Um pacote atual de Desktop e outro de Cloud. Publique cada um quando estiver pronto.</p></div><q-btn flat round icon="mdi-refresh" aria-label="Atualizar pacotes" :disable="busy" @click="load"/></header>
 <div class="distribution-summary"><button v-for="type in ['desktop','cloud']" :key="type" type="button" :aria-pressed="packageType===type" :disabled="busy" @click="packageType=type"><q-icon :name="type==='desktop'?'mdi-microsoft-windows':'mdi-cloud-outline'"/><span><strong>{{type==='desktop'?'Desktop':'Cloud / Render'}}</strong><small>{{distributions[type]?'v'+distributions[type].version+' · '+size(distributions[type].size):'Em breve · nenhum arquivo publicado'}}</small></span><q-badge :color="distributions[type]?'teal-7':'grey-8'" :label="distributions[type]?'Publicado':'Em breve'"/></button></div>
 <div v-if="current" class="package-current"><q-icon name="mdi-check-decagram"/><div><strong>{{kindLabel}} · versão {{current.version}} · {{size(current.size)}}</strong><small>{{current.filename}}</small><p v-if="current.notes">{{current.notes}}</p><code>SHA-256 {{current.sha256}}</code></div><q-btn outline no-caps label="Testar download atual" icon="mdi-download" :disable="busy" @click="testDownload"/></div>
 <q-banner v-else rounded class="package-coming"><q-icon name="mdi-clock-outline" class="q-mr-sm"/>{{kindLabel}} aparece como “Em breve” no painel do cliente. O botão será liberado depois que você publicar o arquivo desta distribuição.</q-banner>
 <q-form @submit.prevent="publish"><h4>{{current?'Substituir o pacote atual':'Publicar o primeiro pacote'}} · {{kindLabel}}</h4><q-tabs v-model="form.source" dense align="left" active-color="teal-3"><q-tab name="file" label="Enviar ZIP/RAR" :disable="busy"/><q-tab name="drive" label="Importar de um link do Drive" :disable="busy"/></q-tabs><div class="package-fields"><q-input dark outlined v-model="form.version" label="Nova versão" maxlength="40" placeholder="1.0.0" :disable="busy"/><q-file v-if="form.source==='file'" dark outlined v-model="form.file" :label="packageType==='desktop'?'ZIP/RAR do instalador':'ZIP/RAR de deploy Cloud'" accept=".zip,.rar" :max-file-size="1073741824" :disable="busy"/><template v-else><q-input dark outlined v-model.trim="form.url" :label="'Link público do Drive · '+kindLabel" :disable="busy"/><q-input dark outlined v-model.trim="form.filename" label="Nome original do arquivo (.zip ou .rar)" :disable="busy"/></template><q-input dark outlined v-model="form.notes" label="Notas e instruções desta versão" type="textarea" autogrow maxlength="3000" :disable="busy" class="package-notes"/></div><q-linear-progress v-if="busy" rounded size="7px" color="teal-4" :value="progress" :indeterminate="form.source==='drive'||progress===1"/><div class="package-actions"><small>O cliente recebe um download privado de uso único. Ao importar do Drive, o servidor copia o arquivo; depois você pode restringir o compartilhamento da origem. A publicação substitui o arquivo atual desta distribuição e remove o anterior do servidor.</small><q-btn unelevated color="teal-7" no-caps type="submit" :label="'Publicar '+kindLabel" icon="mdi-cloud-upload-outline" :loading="busy"/></div></q-form>
 <div class="cloud-guidance" v-if="packageType==='cloud'"><q-icon name="mdi-source-repository"/><p>O cliente deve extrair o pacote e enviar os arquivos para um repositório Git antes de criar o Blueprint no Render. O Render não faz deploy direto de um ZIP. Inclua o <code>render.yaml</code> e o guia de instalação no pacote.</p></div>
</section></template>
<style scoped>
.package-manager{margin:24px 16px;padding:24px;border:1px solid #315e56;border-radius:16px;background:#061d20;color:#effffb}.package-manager header{display:flex;gap:13px;align-items:center}.package-manager header>div{flex:1;min-width:0}.package-manager h3{font-size:20px;line-height:1.4;margin:0}.package-manager h4{font-size:16px;line-height:1.5;margin:25px 0 10px}.package-manager p{font-size:12px;line-height:1.8;color:#adcfc4}.distribution-summary{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:22px 0}.distribution-summary button{display:flex;gap:10px;align-items:center;border:1px solid #3e655b;border-radius:13px;padding:16px;background:#0c2928;color:#d3ecdf;font:inherit;text-align:left;cursor:pointer}.distribution-summary button[aria-pressed=true]{border-color:#8fe0bd;background:#19483b}.distribution-summary button>.q-icon{font-size:26px}.distribution-summary button>span{flex:1;min-width:0}.distribution-summary strong{display:block;font-size:14px;line-height:1.5}.distribution-summary small{display:block;font-size:10px;line-height:1.8;color:#a9c7b8}.package-fields{display:grid;grid-template-columns:1fr 1fr;gap:17px;margin:20px 0}.package-notes{grid-column:1/-1}.package-current{display:flex;align-items:center;gap:12px;border:1px solid #4b9a7d;background:#174137;padding:16px;border-radius:13px;margin:20px 0}.package-current>div{flex:1;min-width:0}.package-current strong,.package-current small{display:block;overflow-wrap:anywhere}.package-current small{font-size:11px;color:#b3d8c9;margin-top:5px}.package-current p{white-space:pre-wrap;margin:9px 0}.package-current code{display:block;overflow-wrap:anywhere;font-size:9px;color:#a8ccb9}.package-actions{display:flex;align-items:center;gap:18px;margin:20px 0}.package-actions small{flex:1;line-height:1.8;color:#9fbdaf}.package-coming{background:#203b38;color:#c0d6c9;font-size:12px;line-height:1.8}.cloud-guidance{display:flex;gap:10px;border-top:1px solid #2f5549;padding-top:15px}.cloud-guidance>.q-icon{font-size:23px;color:#9acbb4}.cloud-guidance p{margin:0;font-size:11px}.package-manager :deep(.q-field__native),.package-manager :deep(.q-field__label){color:#d8eee3}.package-manager :deep(.q-field__control:before){border-color:#52766e}@media(max-width:700px){.package-manager{margin:16px 8px;padding:16px}.package-fields,.distribution-summary{grid-template-columns:1fr}.package-actions,.package-current{flex-wrap:wrap}.package-actions>.q-btn{width:100%}.package-current>div{flex-basis:75%}.package-manager h3{font-size:18px}.distribution-summary button{padding:12px}}
</style>
